using System.Globalization; using System.Text.Json; using Microsoft.Data.Sqlite; using DrawVerify.Core.Interfaces; using DrawVerify.Core.Models;
namespace DrawVerify.Infrastructure.Persistence;
public sealed class SqliteReportTemplateRepository : IReportTemplateRepository, IReportTemplateAuditRepository, IReportTemplatePublisher
{
    private readonly string _connectionString;
    public SqliteReportTemplateRepository(string databasePath) { _connectionString = new SqliteConnectionStringBuilder { DataSource = databasePath }.ToString(); Initialize(); }
    private void Initialize() { using var c = new SqliteConnection(_connectionString); c.Open(); using var command = c.CreateCommand(); command.CommandText = "CREATE TABLE IF NOT EXISTS ReportTemplate (TemplateId TEXT NOT NULL, Version INTEGER NOT NULL, Name TEXT NOT NULL, IsDefault INTEGER NOT NULL, SnapshotJson TEXT NOT NULL, CreatedUtc TEXT NOT NULL, PRIMARY KEY(TemplateId, Version)); CREATE TABLE IF NOT EXISTS ReportTemplateAssignment (ProjectId TEXT NULL, WorkflowId TEXT NULL, TemplateId TEXT NOT NULL, PRIMARY KEY(ProjectId, WorkflowId)); CREATE TABLE IF NOT EXISTS ReportTemplateAudit (AuditId TEXT PRIMARY KEY, TemplateId TEXT NOT NULL, Version INTEGER NOT NULL, ActorId TEXT NOT NULL, TimestampUtc TEXT NOT NULL, Action TEXT NOT NULL, Summary TEXT NOT NULL);"; command.ExecuteNonQuery(); }
    public async Task<IReadOnlyList<ReportTemplate>> ListAsync(CancellationToken token = default) { await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(token); await using var command = c.CreateCommand(); command.CommandText = "SELECT SnapshotJson FROM ReportTemplate t WHERE t.Version=(SELECT MAX(x.Version) FROM ReportTemplate x WHERE x.TemplateId=t.TemplateId) ORDER BY Name"; var result = new List<ReportTemplate>(); await using var reader = await command.ExecuteReaderAsync(token); while (await reader.ReadAsync(token)) result.Add(Read(reader.GetString(0))); return result; }
    public async Task<ReportTemplate?> GetAsync(Guid id, int? version = null, CancellationToken token = default) { await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(token); await using var command = c.CreateCommand(); command.CommandText = version is null ? "SELECT SnapshotJson FROM ReportTemplate WHERE TemplateId=$id ORDER BY Version DESC LIMIT 1" : "SELECT SnapshotJson FROM ReportTemplate WHERE TemplateId=$id AND Version=$version"; command.Parameters.AddWithValue("$id", id.ToString()); if (version is not null) command.Parameters.AddWithValue("$version", version); var value = await command.ExecuteScalarAsync(token); return value is string json ? Read(json) : null; }
    public async Task<ReportTemplate> SaveAsync(ReportTemplate template, int expectedVersion, ReportTemplateAuditEntry audit, CancellationToken token = default) { await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(token); await using var tx = await c.BeginTransactionAsync(token); var current = await CurrentVersion(c, (SqliteTransaction)tx, template.Id, token); if (current != expectedVersion) throw new InvalidOperationException($"Template version conflict: expected {expectedVersion}, current {current}."); var saved = template with { Version = expectedVersion + 1 }; if (saved.IsOrganizationDefault) { await using var clear = c.CreateCommand(); clear.Transaction = (SqliteTransaction)tx; clear.CommandText = "UPDATE ReportTemplate SET IsDefault=0"; await clear.ExecuteNonQueryAsync(token); } await Insert(c, (SqliteTransaction)tx, saved, audit with { Version = saved.Version }, token); await tx.CommitAsync(token); return saved; }
    public async Task<ReportTemplate> PublishAsync(ReportTemplate template, int expectedVersion, ReportTemplateAuditEntry audit, ReportTemplateDocument document, CancellationToken token = default) { await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(token); await using var tx = await c.BeginTransactionAsync(token); var sqliteTx = (SqliteTransaction)tx; var current = await CurrentVersion(c, sqliteTx, template.Id, token); if (current != expectedVersion) throw new InvalidOperationException($"Template version conflict: expected {expectedVersion}, current {current}."); var saved = template with { Version = expectedVersion + 1 }; if (saved.IsOrganizationDefault) { await using var clear = c.CreateCommand(); clear.Transaction = sqliteTx; clear.CommandText = "UPDATE ReportTemplate SET IsDefault=0"; await clear.ExecuteNonQueryAsync(token); } await EnsureDocumentTable(c, sqliteTx, token); await Insert(c, sqliteTx, saved, audit with { Version = saved.Version }, token); await InsertDocument(c, sqliteTx, document with { TemplateId = saved.Id, Version = saved.Version }, token); await tx.CommitAsync(token); return saved; }
    public async Task DeleteAsync(Guid id, int expectedVersion, ReportTemplateAuditEntry audit, CancellationToken token = default) { await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(token); await using var tx = await c.BeginTransactionAsync(token); var current = await CurrentVersion(c, (SqliteTransaction)tx, id, token); if (current != expectedVersion) throw new InvalidOperationException("Template version conflict."); await using var command = c.CreateCommand(); command.Transaction = (SqliteTransaction)tx; command.CommandText = "DELETE FROM ReportTemplate WHERE TemplateId=$id"; command.Parameters.AddWithValue("$id", id.ToString()); await command.ExecuteNonQueryAsync(token); await Audit(c, (SqliteTransaction)tx, audit, token); await tx.CommitAsync(token); }
    public async Task SetDefaultAsync(Guid id, ReportTemplateAuditEntry audit, CancellationToken token = default) { var current = await GetAsync(id, token: token) ?? throw new InvalidOperationException("Template was not found."); await SaveAsync(current with { IsOrganizationDefault = true }, current.Version, audit, token); }
    public async Task<IReadOnlyList<ReportTemplateVersion>> GetVersionsAsync(Guid id, CancellationToken token = default) { await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(token); await using var cmd = c.CreateCommand(); cmd.CommandText = "SELECT Version,CreatedUtc,SnapshotJson FROM ReportTemplate WHERE TemplateId=$id ORDER BY Version"; cmd.Parameters.AddWithValue("$id", id.ToString()); var list = new List<ReportTemplateVersion>(); await using var reader = await cmd.ExecuteReaderAsync(token); while (await reader.ReadAsync(token)) list.Add(new ReportTemplateVersion { TemplateId = id, Version = reader.GetInt32(0), CreatedUtc = DateTimeOffset.Parse(reader.GetString(1), CultureInfo.InvariantCulture), Snapshot = Read(reader.GetString(2)) }); return list; }
    public async Task AssignAsync(ReportTemplateAssignment assignment, ReportTemplateAuditEntry audit, CancellationToken token = default) { if (await GetAsync(assignment.TemplateId, token: token) is null) throw new InvalidOperationException("Template was not found."); await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(token); await using var tx = await c.BeginTransactionAsync(token); await using var cmd = c.CreateCommand(); cmd.Transaction = (SqliteTransaction)tx; cmd.CommandText = "INSERT OR REPLACE INTO ReportTemplateAssignment(ProjectId,WorkflowId,TemplateId) VALUES($project,$workflow,$template)"; cmd.Parameters.AddWithValue("$project", (object?)assignment.ProjectId ?? DBNull.Value); cmd.Parameters.AddWithValue("$workflow", (object?)assignment.WorkflowId ?? DBNull.Value); cmd.Parameters.AddWithValue("$template", assignment.TemplateId.ToString()); await cmd.ExecuteNonQueryAsync(token); await Audit(c, (SqliteTransaction)tx, audit, token); await tx.CommitAsync(token); }
    public async Task<ReportTemplate?> ResolveAsync(string? projectId, string? workflowId, CancellationToken token = default)
    {
        if (!string.IsNullOrWhiteSpace(projectId))
        {
            var project = await ResolveAssignmentAsync(projectId, null, token).ConfigureAwait(false);
            if (project is not null) return project;
        }
        if (!string.IsNullOrWhiteSpace(workflowId))
        {
            var workflow = await ResolveAssignmentAsync(null, workflowId, token).ConfigureAwait(false);
            if (workflow is not null) return workflow;
        }
        return (await ListAsync(token).ConfigureAwait(false)).FirstOrDefault(x => x.IsOrganizationDefault);
    }
    private async Task<ReportTemplate?> ResolveAssignmentAsync(string? projectId, string? workflowId, CancellationToken token)
    {
        await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(token); await using var cmd = c.CreateCommand();
        cmd.CommandText = "SELECT TemplateId FROM ReportTemplateAssignment WHERE ProjectId IS $project AND WorkflowId IS $workflow LIMIT 1";
        cmd.Parameters.AddWithValue("$project", (object?)projectId ?? DBNull.Value); cmd.Parameters.AddWithValue("$workflow", (object?)workflowId ?? DBNull.Value);
        var value = await cmd.ExecuteScalarAsync(token).ConfigureAwait(false);
        return value is string id && Guid.TryParse(id, out var guid) ? await GetAsync(guid, token: token).ConfigureAwait(false) : null;
    }
    public async Task<IReadOnlyList<ReportTemplateAuditEntry>> GetAuditAsync(Guid? id = null, CancellationToken token = default) { await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(token); await using var cmd = c.CreateCommand(); cmd.CommandText = id is null ? "SELECT AuditId,TemplateId,Version,ActorId,TimestampUtc,Action,Summary FROM ReportTemplateAudit ORDER BY TimestampUtc" : "SELECT AuditId,TemplateId,Version,ActorId,TimestampUtc,Action,Summary FROM ReportTemplateAudit WHERE TemplateId=$id ORDER BY TimestampUtc"; if (id is not null) cmd.Parameters.AddWithValue("$id", id.Value.ToString()); var list = new List<ReportTemplateAuditEntry>(); await using var reader = await cmd.ExecuteReaderAsync(token); while (await reader.ReadAsync(token)) list.Add(new ReportTemplateAuditEntry { AuditId=Guid.Parse(reader.GetString(0)), TemplateId=Guid.Parse(reader.GetString(1)), Version=reader.GetInt32(2), ActorId=reader.GetString(3), TimestampUtc=DateTimeOffset.Parse(reader.GetString(4), CultureInfo.InvariantCulture), Action=reader.GetString(5), Summary=reader.GetString(6) }); return list; }
    public async Task RecordAuditAsync(ReportTemplateAuditEntry entry, CancellationToken token = default) { await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(token); await using var tx = await c.BeginTransactionAsync(token); await Audit(c, (SqliteTransaction)tx, entry with { Summary = entry.Summary.Length > 512 ? entry.Summary[..512] : entry.Summary }, token); await tx.CommitAsync(token); }
    private static ReportTemplate Read(string json) => JsonSerializer.Deserialize<ReportTemplate>(json) ?? throw new InvalidOperationException("Stored report template is invalid.");
    private static async Task<int> CurrentVersion(SqliteConnection c, SqliteTransaction tx, Guid id, CancellationToken token) { await using var cmd=c.CreateCommand(); cmd.Transaction=tx; cmd.CommandText="SELECT COALESCE(MAX(Version),0) FROM ReportTemplate WHERE TemplateId=$id"; cmd.Parameters.AddWithValue("$id",id.ToString()); return Convert.ToInt32(await cmd.ExecuteScalarAsync(token), CultureInfo.InvariantCulture); }
    private static async Task Insert(SqliteConnection c, SqliteTransaction tx, ReportTemplate t, ReportTemplateAuditEntry audit, CancellationToken token) { await using var cmd=c.CreateCommand(); cmd.Transaction=tx; cmd.CommandText="INSERT INTO ReportTemplate VALUES($id,$version,$name,$default,$json,$created)"; cmd.Parameters.AddWithValue("$id",t.Id.ToString()); cmd.Parameters.AddWithValue("$version",t.Version); cmd.Parameters.AddWithValue("$name",t.Name); cmd.Parameters.AddWithValue("$default",t.IsOrganizationDefault?1:0); cmd.Parameters.AddWithValue("$json",JsonSerializer.Serialize(t)); cmd.Parameters.AddWithValue("$created",DateTimeOffset.UtcNow.ToString("O")); await cmd.ExecuteNonQueryAsync(token); await Audit(c,tx,audit,token); }
    private static async Task EnsureDocumentTable(SqliteConnection c, SqliteTransaction tx, CancellationToken token) { await using var cmd = c.CreateCommand(); cmd.Transaction = tx; cmd.CommandText = "CREATE TABLE IF NOT EXISTS ReportTemplateDocument (TemplateId TEXT NOT NULL, Version INTEGER NOT NULL, SourceId TEXT NOT NULL, SourceFileName TEXT NOT NULL, Content BLOB NOT NULL, CreatedUtc TEXT NOT NULL, PRIMARY KEY(TemplateId, Version))"; await cmd.ExecuteNonQueryAsync(token); }
    private static async Task InsertDocument(SqliteConnection c, SqliteTransaction tx, ReportTemplateDocument d, CancellationToken token) { await using var cmd=c.CreateCommand(); cmd.Transaction=tx; cmd.CommandText="INSERT INTO ReportTemplateDocument VALUES($id,$version,$source,$name,$content,$created)"; cmd.Parameters.AddWithValue("$id",d.TemplateId.ToString()); cmd.Parameters.AddWithValue("$version",d.Version); cmd.Parameters.AddWithValue("$source",d.SourceId.ToString()); cmd.Parameters.AddWithValue("$name",d.SourceFileName); cmd.Parameters.Add("$content",SqliteType.Blob).Value=d.Content; cmd.Parameters.AddWithValue("$created",d.CreatedUtc.ToString("O")); await cmd.ExecuteNonQueryAsync(token); }
    private static async Task Audit(SqliteConnection c, SqliteTransaction tx, ReportTemplateAuditEntry a, CancellationToken token) { await using var cmd=c.CreateCommand(); cmd.Transaction=tx; cmd.CommandText="INSERT INTO ReportTemplateAudit VALUES($id,$template,$version,$actor,$timestamp,$action,$summary)"; cmd.Parameters.AddWithValue("$id",a.AuditId.ToString()); cmd.Parameters.AddWithValue("$template",a.TemplateId.ToString()); cmd.Parameters.AddWithValue("$version",a.Version); cmd.Parameters.AddWithValue("$actor",a.ActorId); cmd.Parameters.AddWithValue("$timestamp",a.TimestampUtc.ToString("O")); cmd.Parameters.AddWithValue("$action",a.Action); cmd.Parameters.AddWithValue("$summary",a.Summary); await cmd.ExecuteNonQueryAsync(token); }
}
